function dir$phixe(p){
  this.constructor(p);
}
dir$phixe.prototype = new DirEvent();
dir$phixe.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}

				dir$phixe.prototype.afterInit = function(){
					var p = this._dir, g = p.grid(), phixect = p.grid(1);
					var exp = {
						tien: ['*tien', '[so_luong] * [gia]'],
						tien_tong: ['*tien_tong','[tien] / [tyle]'],


						t_so_luong: ['@t_so_luong','[so_luong]'],

						t_tien: ['@t_tien','[tien] / [tyle]'],
						}
						p.applyExpression(exp, g, false);

  var expForm = {
    t_tt_nt: ['#t_tt_nt', '[t_tien_nt2] + [t_thue_nt]'],
    t_tt: ['#t_tt', '[t_tien2] + [t_thue] + [t_phi]']
  }
  p.applyExpressionForm(expForm, true);

				g.FomulaApplied = {
					"so_luong":["t_so_luong","tien","tong_tien","t_tien"],
					"gia":["tien","tien_tong","t_tien"],
					"tyle":["tien_tong","t_tien"],

			      } //Gan lai valid của từng cột sẽ tính các công thức nào theo thứ tự.
				}


  p.options.FCColumns = {FC: ['t_tien_nt2', 't_thue_nt', 't_tt_nt', 't_tc_tien_nt2'], BC: ['t_tien2', 't_thue', 't_tt', 't_tc_tien2']};
  g.FCColumns = {FC: ['gia_nt2', 'tien_nt2'], BC: ['gia2', 'tien2']};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
  p.setFCHidden(oTG.fval());
  p.calcExpressionAll(0, 't_ex_total');

  p.setColumnAuth(0, ['ma_lo', 'ma_vi_tri'], true); // Ko sd ma_lo, ma_vi_tri
  dir$phixeDisabledMasterField(p, g);
  dir$phixeHiddenColumnByType(p);
  dir$phixeHiddenColumnByTran(p);
  dir$phixeHiddenColumnByDay(p);
  dir$phixeDisabledStatusByAction(p);
  p.find(".control-label.t_so_luong, .control-label.t_tien_nt2, .control-label.t_thue_nt, .control-label.t_tt_nt, .input-field.t_so_luong, .input-field.t_tien_nt2, .input-field.t_tien2, .input-field.t_thue_nt, .input-field.t_thue, .input-field.t_tt_nt, .input-field.t_tt").css("font-weight", "bold");



dir$phixe.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    default:
      break;
  }
  return true;
}

dir$phixe.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$phixeHiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$phixeHiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_dk_ngay':
      dir$phixeHiddenColumnByDay(p);
      break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$phixe.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$phixeDisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$phixeDisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_phi].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
  if (p.options._sale_lock_master == 1) p.setDisabled(['ma_kh', 'ngay_ct', 'ma_nt'], dis);
}
function dir$phixeHiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
}
function dir$phixeHiddenColumnByTran(p){

}

function dir$phixeHiddenColumnByDay(p){
	var v = p.valForm('ma_dk_ngay');
	if (v == 1) p.request('ma_dk_ngay', '', ['t2_yn','t3_yn','t4_yn','t5_yn','t6_yn','t7_yn','t8_yn']);
	p.setDisabled(['t2_yn','t3_yn','t4_yn','t5_yn','t6_yn','t7_yn','t8_yn'], v == 1);
	}

function dir$phixeDisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}





